def clean_inventory_and_favorites(apps, schema_editor):
    Inventory = apps.get_model('catalog', 'PiezaInventario')
    Favorite = apps.get_model('catalog', 'Favorito')
    Inventory.objects.exclude(
        estado_adquisicion__in=['ADQUIRIDA', 'DESEADA']
    ).update(estado_adquisicion='ADQUIRIDA')
    Inventory.objects.exclude(visibilidad__in=['PUBLICA', 'PRIVADA']).update(
        visibilidad='PRIVADA'
    )
    Inventory.objects.exclude(condicion__in=['NUEVA', 'USADA', 'DAÑADA']).update(
        condicion='USADA'
    )
    seen = set()
    duplicate_ids = []
    for favorite in Favorite.objects.order_by('id').iterator():
        pair = (favorite.user_id, favorite.pieza_inventario_id)
        if pair in seen:
            duplicate_ids.append(favorite.id)
        else:
            seen.add(pair)
    Favorite.objects.filter(id__in=duplicate_ids).delete()


